SELECT School, EILName
FROM schools
WHERE CDSCode = '1612590136051';

SELECT ROUND(
  100.0 * COUNT(*) FILTER (WHERE NOT EXISTS (
    SELECT 1
    FROM member
    WHERE member.link_to_major = major.major_id
  )) / COUNT(*),
  2
) AS percentage_majors_without_members
FROM major;

SELECT 100.0 * COUNT(DISTINCT CASE WHEN CAST(strftime('%Y', Birthday) AS INTEGER) >= 1960 THEN ID END) / COUNT(DISTINCT ID) AS percentage
FROM Patient
WHERE LOWER(Diagnosis) LIKE '%psoriatic arthritis%';

SELECT COUNT(DISTINCT ID) AS patient_count
FROM Patient
WHERE Diagnosis LIKE '%psoriatic arthritis%';
